import Foundation

func merge(_ first: Int, _ second: Int) -> (set: Int, changes: Int) { let common = first & second; return common != 0 ? (common, 0) : (first | second, 1) }
func provisional(_ rooted: Rooted, _ pattern: [Int]) -> (sets: [Int: Int], changes: Int) { var sets: [Int: Int] = [:], changes = 0; for node in rooted.order.reversed() { if node < rooted.tree.size { sets[node] = pattern[node] } else { let children = rooted.children[node]!.filter { $0 != rooted.outgroup }, result = merge(sets[children[0]]!, sets[children[1]]!); sets[node] = result.set; changes += result.changes; if node == rooted.root { changes += merge(result.set, sets[rooted.outgroup]!).changes } } }; return (sets, changes) }
func patternScores(_ tree: Tree, _ patterns: Patterns, _ outgroup: Int) -> [Int] { let rooted = tree.rooted(outgroup); return patterns.encoded.map { provisional(rooted, $0).changes } }
func parsimonyScore(_ tree: Tree, _ patterns: Patterns, _ outgroup: Int) -> Int { let changes = patternScores(tree, patterns, outgroup); return changes.indices.reduce(0) { $0 + changes[$1] * patterns.weights[$1] } }
struct Reconstruction { let ancestors: [Int: String]; let branchChanges: [NodePair: Int]; let siteChanges: [Int] }
func reconstruct(_ tree: Tree, _ patterns: Patterns, _ outgroup: Int) -> Reconstruction {
    let rooted = tree.rooted(outgroup)
    var ancestors = Dictionary(uniqueKeysWithValues: tree.internalNodes.map { ($0, [UInt8]()) }), changes = Dictionary(uniqueKeysWithValues: tree.edges.map { (NodePair($0.first, $0.second), 0) }), scores: [Int] = []
    for (index, pattern) in patterns.encoded.enumerated() { let result = provisional(rooted, pattern), sets = result.sets, combined = merge(sets[rooted.root]!, sets[outgroup]!).set, firstBase = combined & -combined; scores.append(result.changes); var states: [Int: Int] = [:]; for node in [rooted.root, outgroup] { let set = sets[node]!; states[node] = set & firstBase != 0 ? firstBase : set & -set }; for node in rooted.order.dropFirst() where node != outgroup { let parent = states[rooted.parents[node]!]!, set = sets[node]!; states[node] = set & parent != 0 ? parent : set & -set }; for node in tree.internalNodes { ancestors[node]!.append(baseSymbols[states[node]!.trailingZeroBitCount]) }; for edge in tree.edges where states[edge.first]! != states[edge.second]! { changes[NodePair(edge.first, edge.second)]! += patterns.weights[index] } }
    let sequences = Dictionary(uniqueKeysWithValues: tree.internalNodes.map { node in (node, String(decoding: patterns.columns.map { ancestors[node]![$0] }, as: UTF8.self)) })
    return Reconstruction(ancestors: sequences, branchChanges: changes, siteChanges: patterns.columns.map { scores[$0] })
}
struct Branch { let mask: Int; let parent: Int; let child: Int }
func branches(_ tree: Tree, _ outgroup: Int) -> [Branch] { let rooted = tree.rooted(outgroup); return rooted.order.dropFirst().map { Branch(mask: $0 == outgroup ? rooted.ingroup : rooted.masks[$0]!, parent: rooted.parents[$0]!, child: $0) }.sorted { first, second in if first.mask != second.mask { return first.mask < second.mask }; if first.parent != second.parent { return first.parent < second.parent }; return first.child < second.child } }
func insert(_ tree: Tree, _ first: Int, _ second: Int, _ taxon: Int) -> Tree { var result = tree; result.disconnect(first, second); let node = result.internalNode(); result.adjacent[taxon] = [:]; result.connect(first, node); result.connect(second, node); result.connect(taxon, node); return result }
struct NNICandidate { let mask: Int; let swap: Int; let tree: Tree }
func nniCandidates(_ tree: Tree, _ outgroup: Int) -> [NNICandidate] { let rooted = tree.rooted(outgroup); var candidates: [NNICandidate] = []; for branch in branches(tree, outgroup) where branch.parent >= tree.size && branch.child >= tree.size { let first = branch.parent, second = branch.child, sibling = rooted.children[first]!.first { $0 != second && $0 != outgroup }!, children = rooted.children[second]!.sorted { rooted.masks[$0]! < rooted.masks[$1]! }; for (index, child) in children.enumerated() { var result = tree; let siblingLength = result.disconnect(first, sibling), childLength = result.disconnect(second, child); result.connect(first, child, childLength); result.connect(second, sibling, siblingLength); candidates.append(NNICandidate(mask: branch.mask, swap: index + 1, tree: result)) } }; return candidates }
